            }
            BigDecimal score = settled.movePointLeft(2).subtract(BigDecimal.valueOf(5L * overdue))
                    .setScale(0, RoundingMode.HALF_EVEN);
            scores.put(person.getId(), new Score(person.getName(), score.toPlainString()));
