test("score lines scenario 3", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-20");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "1.50");
  await ui.setSetting(pg_uma, "floor", "2.00");
  await ui.setSetting(pg_uma, "late-pct", "5.00");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-15");
  await ui.setSetting(pg_uma, "proof-threshold", "3.00");
  await ui.setSetting(pg_uma, "grace-days", "3");
  await ui.setSetting(pg_uma, "note-threshold", "1.00");
  await ui.setSetting(pg_uma, "entry-date", "2026-03-05");
  await ui.setSetting(pg_uma, "fiscal-start-month", "4");
  await ui.setSetting(pg_uma, "alert-threshold", "3.00");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "12.50"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C", "terms": "20", "contact": "ben@x"}));
  expect(await ui.addPool(pg_uma, "P1")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Cam", "share": "60.00"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ben", "share": "40.00"})).toBe(true);
  expect(await ui.editPerson(pg_uma, p_ben, {"terms": "3", "termsFrom": "2026-03-12"})).toBe(true);
  expect(await ui.addPatron(pg_uma, p_ben, "Cam")).toBe(true);
  const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "12.50", "date": "2026-02-25", "ref": "inv 7", "tags": "a, B"}));
  expect(await ui.statement(pg_uma, p_ben)).toBe(true);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.unstate(pg_wes, p_ben)).toBe(true);
  const c_ben_0 = ui.must(await ui.addClaim(pg_wes, p_ben, {"amount": "4.00", "date": "2026-03-05"}));
  await ui.refresh(pg_wes);
  expect(await ui.delegate(pg_wes, {"user": "uma", "from": "2026-03-15", "to": "2026-03-20"})).toBe(true);
  await ui.refresh(pg_uma);
  expect(await ui.periodAction(pg_uma, "P1", "close")).toBe(true);
  await ui.refresh(pg_uma);
  const c_cam_1 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "3.33", "date": "2026-03-05", "note": "n"}));
  expect(await ui.claimEditOpen(pg_uma, c_ben_0)).toBe(false);
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.claimEditOpen(pg_vic, c_ben_0)).toBe(false);
